package app.quietreader.discovery;

import app.quietreader.Models.Source;
import java.util.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class InterestBandTest {
    private HotCandidate item(Source source,int id,String title){return new HotCandidate(source,source==Source.V2EX?"https://www.v2ex.com/t/"+id:"https://www.thepaper.cn/newsDetail_forward_"+id,title,"合成中文摘要","",false,id,null,1000);}
    private FeedStore.Row row(String id,int band){HotCandidate candidate=item(Source.V2EX,100+Math.floorMod(id.hashCode(),100000),"分层持久化测试"+id);return new FeedStore.Row(id,candidate,"",List.of(candidate),band);}
    @Test public void allTypedBandsSurviveJsonRoundTrip(){for(int band=0;band<3;band++){FeedStore.Row original=row("event",band),restored=FeedStore.Row.read(original.eventId,original.payload().toString(),original.reason);assertEquals(band,restored.interestBand);assertEquals(original.candidate.textHash,restored.candidate.textHash);assertEquals(original.entries.get(0).id,restored.entries.get(0).id);}}
    @Test public void legacyExplanationDoesNotBecomeClassification(){FeedStore.Row original=row("legacy",-1);JSONObject payload=original.payload();assertFalse(payload.has("interestBand"));FeedStore.Row restored=FeedStore.Row.read(original.eventId,payload.toString(),"接近你选择的：一个看起来很确定的解释");assertEquals(-1,restored.interestBand);}
    @Test public void malformedOrFutureBandsFailClosed() throws Exception {FeedStore.Row original=row("event",0);for(Object band:new Object[]{"0",-1,3,.5,JSONObject.NULL}){JSONObject value=original.payload().put("interestBand",band);assertEquals(-1,FeedStore.Row.read("event",value.toString(),"").interestBand);}assertEquals(-1,FeedStore.Row.read("event",original.payload().put("interestBandVersion","future-version").toString(),"").interestBand);}
    @Test public void sourceRepresentativeChangesKeepAcceptedEventBand(){HotCandidate a=item(Source.V2EX,100,"共同事件的中文标题"),b=item(Source.THEPAPER,101,"共同事件的另一个来源");FeedStore.Row group=new FeedStore.Row("group",a,"",List.of(a,b),2);FeedStore.Row filtered=SourceFilter.apply(List.of(group),"THEPAPER").get(0);assertEquals(b.id,filtered.candidate.id);assertEquals(2,filtered.interestBand);assertEquals(2,new PlatformPreference(new JSONArray()).apply(List.of(group)).get(0).interestBand);}
    @Test public void realSemanticClassificationSurvivesFusionAndPlatformStage() throws Exception {HotCandidate positive=item(Source.V2EX,101,"手机电池续航与散热"),neutral=item(Source.V2EX,102,"天文学家发现新行星"),negative=item(Source.V2EX,103,"明星红毯造型讨论");JSONArray feedback=new JSONArray().put(new JSONObject().put("id","p").put("scope","sample").put("action","MORE").put("sample",positive.modelText())).put(new JSONObject().put("id","n").put("scope","sample").put("action","LESS").put("sample",negative.modelText()));SemanticOrder.Profile profile=new SemanticOrder.Profile(feedback);float[] p=new float[512],n=new float[512];p[0]=1;n[1]=1;Map<String,float[]> vectors=Map.of(SemanticOrder.key(positive.modelText()),p,SemanticOrder.key(neutral.modelText()),n);List<SemanticOrder.Scored> scored=SemanticOrder.rank(List.of(new FeedStore.Row("negative",negative,""),new FeedStore.Row("neutral",neutral,""),new FeedStore.Row("positive",positive,"")),profile,vectors);List<FeedStore.Row> fused=SemanticOrder.fuse(scored,Map.of(),profile.platforms);assertEquals(List.of("positive","neutral","negative"),fused.stream().map(r->r.eventId).toList());assertEquals(List.of(0,1,2),fused.stream().map(r->r.interestBand).toList());}
    @Test public void noveltyDoesNotCrossKnownOrUnclassifiedBarriers(){FeedStore.Row highSeen=row("high-seen",0),highNew=row("high-new",0),unknown=row("unknown",-1),neutral=row("neutral-new",1),negative=row("negative-new",2);Map<String,FeedRefreshOrder.Recent> history=Map.of(highSeen.eventId,new FeedRefreshOrder.Recent(9000,9000,0));assertEquals(List.of(highNew,highSeen,unknown,neutral,negative),FeedRefreshOrder.forRows(List.of(highSeen,highNew,unknown,neutral,negative),history,10000));}
    @Test public void unknownLegacyRowsRemainStableDespitePlausibleHistory(){FeedStore.Row seen=row("seen",-1),fresh=row("fresh",-1);assertEquals(List.of(seen,fresh),FeedRefreshOrder.forRows(List.of(seen,fresh),Map.of("seen",new FeedRefreshOrder.Recent(9000,9000,0)),10000));}
    @Test public void noncontiguousSameBandNeverJumpsOverAnotherBand(){FeedStore.Row seen=row("seen",0),negative=row("negative",2),fresh=row("fresh",0);assertEquals(List.of(seen,negative,fresh),FeedRefreshOrder.forRows(List.of(seen,negative,fresh),Map.of("seen",new FeedRefreshOrder.Recent(9000,0,0)),10000));}
    @Test public void persistedBaseOrderRestoresRelevanceAfterCooldown(){FeedStore.Row seen=row("seen",0).withRefreshBasePosition(0),fresh=row("fresh",0).withRefreshBasePosition(1);List<FeedStore.Row> novelty=FeedRefreshOrder.forRows(List.of(fresh,seen),Map.of("seen",new FeedRefreshOrder.Recent(9000,0,0)),10000);assertEquals(List.of(fresh,seen),novelty);assertEquals(List.of(seen,fresh),FeedRefreshOrder.forRows(novelty,Map.of("seen",new FeedRefreshOrder.Recent(9000,0,0)),10000+FeedRefreshOrder.SHOWN_COOLDOWN_MS));}
    @Test public void incompleteOrDuplicateBaseOrderDoesNotGuess(){FeedStore.Row a=row("a",0).withRefreshBasePosition(0),b=row("b",0).withRefreshBasePosition(0),unknown=row("unknown",-1);assertEquals(List.of(b,a),FeedRefreshOrder.forRows(List.of(b,a),Map.of(),10000));assertEquals(List.of(unknown,a),FeedRefreshOrder.forRows(List.of(unknown,a),Map.of(),10000));}
    @Test public void basePositionSurvivesPayloadAndRepresentativeChange(){HotCandidate a=item(Source.V2EX,100,"同事件不同入口"),b=item(Source.THEPAPER,101,"同事件另一来源");FeedStore.Row group=new FeedStore.Row("group",a,"",List.of(a,b),1,42);FeedStore.Row restored=FeedStore.Row.read("group",group.payload().toString(),"");assertEquals(42,restored.refreshBasePosition);assertEquals(42,SourceFilter.apply(List.of(restored),"THEPAPER").get(0).refreshBasePosition);assertEquals(42,new PlatformPreference(new JSONArray()).apply(List.of(restored)).get(0).refreshBasePosition);}
}
